$filename='mgoutlet-events-'.$from->format('Y-m-d').($from==$to?'':'-do-'.$to->format('Y-m-d')).'.csv'; header('Content-Type: text/csv; charset=UTF-8'); header('Content-Disposition: attachment; filename="'.$filename.'"'); header('Cache-Control: no-store'); echo "\xEF\xBB\xBF"; $out=fopen('php://output','w'); fputcsv($out,['timestamp','date','time','event_type','path','country','region','city','device_class','client_class'],';'); foreach($rows as $r){$dt=new DateTimeImmutable((string)($r['timestamp']??'')); fputcsv($out,[$dt->format('Y-m-d H:i:s'),$dt->format('Y-m-d'),$dt->format('H:i:s'),$r['event_type']??'',$r['path']??'',$r['country']??'',$r['region']??'',$r['city']??'',$r['device_class']??'',$r['client_class']??''],';');}
